// one icon for the page: inline SVG, tinted by the CSS colour (or in its own colours)
function gameIcon(k,cls=""){ const g=GAME_ICONS[k]; if(g) return `<svg class="gi ofc ${cls}" viewBox="${g[0]}" aria-hidden="true">${g[1]}</svg>`;
  const c=GAME_COLOR[k]; return c?`<svg class="gi gi-color ${cls}" viewBox="${c[0]}" aria-hidden="true">${c[1]}</svg>`:""; }
// "ship:<key>": a ship's own icon (shipicons.js), drawn like the rest
const gameIconUrl=(k,color="#fff")=>{ if(String(k).includes(":")&&!String(k).startsWith("ship:")&&typeof iconUrl==="function") return iconUrl(k,color);   // any app icon (iconlib.js): a waypoint's own
  const g=GAME_ICONS[k]||GAME_COLOR[k]||(String(k).startsWith("ship:")&&typeof SHIP_ICONS!=="undefined"?SHIP_ICONS[k.slice(5)]:null); if(!g) return null;
  return "data:image/svg+xml,"+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="${g[0]}"${GAME_COLOR[k]?"":` fill="${color}"`}>${g[1]}</svg>`); };
// The symbol a place gets on the map and its card: by name first (spaceports, Wikelo's emporiums), then by kind.
// null: the map's own drawing for that kind (Lagrange points).
function locIcon(L){ if(!L) return null; const n=L.name||"";
  if(/wikelo/i.test(n)) return "wikelo";
  if(/spaceport/i.test(n)) return "spaceport";
  return {city:"settlement",station:"space_station",outpost:"outpost",field:"mining",cave:"cave",comm:"comm_array",wreck:"vehicle_medium",
    jump:"quantum_nav",om:"jump_point",poi:"generic_marker"}[L.type]||null; }
// The map: icon k ready to draw at px x px (device pixels) in a colour. null while it loads or if it's missing,
// so the caller draws its old shape for now. Each colour and size is made once and kept.
const _giSrc=new Map(), _giOut=new Map();
function gameIconCanvas(k,color,px){ px=Math.max(8,Math.round(px)); const key=k+"|"+color+"|"+px;
  if(_giOut.has(key)) return _giOut.get(key);
  let s=_giSrc.get(k);
  if(!s){ const url=gameIconUrl(k); if(!url){ _giOut.set(key,null); return null; }
    s={img:new Image(),ok:null,tint:!GAME_COLOR[k]&&!(typeof iconById==="function"&&iconById(k)?.mode==="own")}; _giSrc.set(k,s);
    s.img.onload=()=>{ s.ok=true; }; s.img.onerror=()=>{ s.ok=false; }; s.img.src=url; }
  if(s.ok===null) return null;                                          // still loading: try again next frame
  if(!s.ok){ _giOut.set(key,null); return null; }
  const cv=document.createElement("canvas"); cv.width=cv.height=px; const c=cv.getContext("2d");
  c.drawImage(s.img,0,0,px,px);                                        // every icon is square (an SVG's own size can't be trusted)
  if(s.tint){ c.globalCompositeOperation="source-in"; c.fillStyle=color; c.fillRect(0,0,px,px); }
  _giOut.set(key,cv); return cv; }
// The class list for a place's little type mark (.ty): its kind, plus spaceport / wikelo when it gets that symbol
function tyClass(L){ if(!L) return ""; if(L.source==="user") return "wp"; if(L.source==="mission") return "mission";
  const gi=locIcon(L); return L.type+(gi==="spaceport"||gi==="wikelo"?" "+gi:""); }
// draw icon k centred on (x,y), size css pixels across, on the map's 2D canvas; false if it isn't ready
function drawGameIcon(c,k,x,y,size,color){ const cv=gameIconCanvas(k,color,size*(window.devicePixelRatio||1)); if(!cv) return false;
  c.drawImage(cv,x-size/2,y-size/2,size,size); return true; }
// the legend's / cards' little type marks (.ty.station ...) use the same shapes as CSS masks
(()=>{ const r=document.documentElement.style;
  for(const [t,k] of [["city","settlement"],["station","space_station"],["outpost","outpost"],["field","mining"],["cave","cave"],
    ["comm","comm_array"],["wreck","vehicle_medium"],["wp","nav_destination"],["mission","objective"],["jump","quantum_nav"],["om","jump_point"],["poi","generic_marker"],["spaceport","spaceport"],["wikelo","wikelo"]])
    r.setProperty("--gi-"+t,`url("${gameIconUrl(k)}")`); })();
